package com.aliothmoon.maafw.once;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NativeUiStructureV50ParserTest {
 static String s(String n,String d){return "Search to earn, Search in Bing everyday to earn Rewards points, "+n+" out of "+d+" points earned";}
 static String r(String n,String d){return "Read to earn, Read news everyday to earn Rewards points, "+n+" out of "+d+" points earned";}
 static NativeUiStructureParser.Node node(int i,int parent,String t,String d){return new NativeUiStructureParser.Node(i,parent,true,true,t,d);}
 static NativeUiStructureParser.Result parse(String... fields){List<NativeUiStructureParser.Node> n=new ArrayList<>();for(int i=0;i<fields.length;i++)n.add(node(i,i==0?-1:0,fields[i],null));return NativeUiStructureV50Parser.parse(n);}
 static void known(NativeUiStructureParser.TaskResult t,int n,int d){assertEquals(NativeUiStructureParser.Status.KNOWN,t.status());assertEquals(n,t.current());assertEquals(d,t.target());assertEquals(1,t.matchCount());assertEquals(NativeUiStructureParser.Unit.EXPLICIT_TEXT_POINTS,t.unit());}
 @Test public void bothExactNewFields(){var x=parse(s("51","60"),r("0","30"));known(x.search(),51,60);known(x.reading(),0,30);assertFalse(x.actionAuthority());}
 @Test public void originalGrammarStillDelegated(){var x=parse("Search to earn, , 2 out of 60 points earned","阅读以赚取, , 已赚取 0 积分(需要 30 积分)");known(x.search(),2,60);known(x.reading(),0,30);}
 @Test public void equalTextDescriptionDeduplicated(){var x=NativeUiStructureV50Parser.parse(List.of(node(0,-1,s("1","60"),s("1","60"))));known(x.search(),1,60);}
 @Test public void duplicateNodesAmbiguous(){var x=parse(s("1","60"),s("1","60"));assertEquals(NativeUiStructureParser.Status.AMBIGUOUS,x.search().status());assertEquals(2,x.search().matchCount());}
 @Test public void mixedOldNewAmbiguous(){var x=parse("Search to earn, , 1 out of 60 points earned",s("1","60"));assertEquals(NativeUiStructureParser.Status.AMBIGUOUS,x.search().status());assertEquals(2,x.search().matchCount());}
 @Test public void distinctFieldsSameNodeAmbiguous(){var x=NativeUiStructureV50Parser.parse(List.of(node(0,-1,s("1","60"),s("2","60"))));assertEquals(NativeUiStructureParser.Status.AMBIGUOUS,x.search().status());}
 @Test public void swappedDescriptionsInvalid(){var x=parse(s("1","60").replace("Search in Bing everyday", "Read news everyday"),r("0","30").replace("Read news everyday", "Search in Bing everyday"));assertEquals(NativeUiStructureParser.Status.INVALID,x.search().status());assertEquals(NativeUiStructureParser.Status.INVALID,x.reading().status());}
 @Test public void arbitraryFullSummaryDescriptionInvalid(){assertEquals(NativeUiStructureParser.Status.INVALID,parse("Search to earn, Unrecognized description, 1 out of 60 points earned").search().status());}
 @Test public void signsOverflowZeroAndRegressionInvalid(){for(String n:new String[]{"-1","+1","1.0","NaN","10001","999999999999999999999999"})assertEquals(n,NativeUiStructureParser.Status.INVALID,parse(s(n,"10000")).search().status());for(String d:new String[]{"0","-1","+60","10001","999999999999999999999"})assertEquals(d,NativeUiStructureParser.Status.INVALID,parse(r("0",d)).reading().status());assertEquals(NativeUiStructureParser.Status.INVALID,parse(s("61","60")).search().status());}
 @Test public void numericBounds(){known(parse(s("10000","10000")).search(),10000,10000);known(parse(r("0","1")).reading(),0,1);}
 @Test public void trailingNewlineOrSpacesNotAccepted(){for(String extra:new String[]{"\n","\r\n"," "," trailing"})assertEquals(NativeUiStructureParser.Status.INVALID,parse(s("1","60")+extra).search().status());}
 @Test public void fixedSpellingPunctuationAndCaseAreNotRelaxed(){for(String v:new String[]{s("1","60").replace("everyday","every day"),s("1","60").replace("points,","points ,"),s("1","60").replace("Rewards","rewards"),s("1","60").replace(", 1",",  1")})assertNotEquals(NativeUiStructureParser.Status.KNOWN,parse(v).search().status());}
 @Test public void noJoining(){var x=parse("Read to earn","Read news everyday to earn Rewards points","0 out of 30 points earned");assertEquals(NativeUiStructureParser.Status.UNKNOWN,x.reading().status());}
 @Test public void completionShorthandStillUnknown(){var x=parse("Read to earn, 30 points earned","Search to earn, 60 points earned");assertEquals(NativeUiStructureParser.Status.UNKNOWN,x.search().status());assertEquals(NativeUiStructureParser.Status.UNKNOWN,x.reading().status());}
 @Test public void otherTaskDoesNotBorrow(){var x=parse(r("0","30"));assertEquals(NativeUiStructureParser.Status.UNKNOWN,x.search().status());known(x.reading(),0,30);}
 @Test public void malformedOneTaskDoesNotPoisonOther(){var x=parse(s("+1","60"),r("0","30"));assertEquals(NativeUiStructureParser.Status.INVALID,x.search().status());known(x.reading(),0,30);}
 @Test public void oldInvalidCannotBeRepaired(){var x=parse("Read to earn, , +1 out of 30 points earned",r("0","30"));assertEquals(NativeUiStructureParser.Status.INVALID,x.reading().status());}
 @Test public void hiddenAndForeignFieldsIgnored(){var x=NativeUiStructureV50Parser.parse(List.of(new NativeUiStructureParser.Node(0,-1,false,true,s("1","60"),null),new NativeUiStructureParser.Node(1,0,true,false,r("0","30"),null)));assertEquals(NativeUiStructureParser.Status.UNKNOWN,x.search().status());assertEquals(NativeUiStructureParser.Status.UNKNOWN,x.reading().status());}
 @Test public void invalidShapeInherited(){for(List<NativeUiStructureParser.Node> n:Arrays.asList(null,Arrays.asList((NativeUiStructureParser.Node)null),List.of(node(0,2,s("1","60"),null)),List.of(node(0,-1,s("1","60"),null),node(0,0,r("0","30"),null)),List.of(node(0,-1,"x".repeat(2049),null)))){var x=NativeUiStructureV50Parser.parse(n);assertEquals(NativeUiStructureParser.Status.INVALID,x.search().status());assertEquals(NativeUiStructureParser.Status.INVALID,x.reading().status());}}
 @Test public void batchLimitsInherited(){List<NativeUiStructureParser.Node> n=new ArrayList<>();for(int i=0;i<513;i++)n.add(node(i,i==0?-1:0,"",null));assertEquals(NativeUiStructureParser.Status.INVALID,NativeUiStructureV50Parser.parse(n).search().status());n.clear();for(int i=0;i<17;i++)n.add(node(i,i==0?-1:0,"x".repeat(2048),null));assertEquals(NativeUiStructureParser.Status.INVALID,NativeUiStructureV50Parser.parse(n).reading().status());}
}
